	(28, '2026-IBA-00005', 'HAHA 65 s. 2026', 'TYRONE', NULL, NULL, '4c445eb47ac57aa1393473186a29973748166371443d459c193e6af12d75f0fe', 'DUMMY FILE', '', 4, 3, 3, '2026-07-13', 'Archived', 'file_6a54a410e72513.58061495.docx', 'Systems_Integration_Activity_Handout.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 25241, 'c251dd2ae71e154db50c95e7c2d310ebb6b717749b3f2f9d7af4c7081d1bbd28', 1, '2026-07-13 16:38:40', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, NULL, '2026-07-13 16:38:40', 19, NULL, NULL, NULL, NULL, NULL, 'Fulfilled', '2026-07-13 16:39:27', 19, 19, '2026-07-13 16:38:40', '2026-07-13 16:39:27', NULL, NULL, NULL),
	(29, '2026-IBA-00006', 'No. 114-A s. 2023', 'MEMORANDUM', NULL, NULL, '9b0f3f3c69c04fa17777f3bb502b6a22eff2dca4c09ec6217d87c6bb14bde305', 'EXTENDED PRMSU WELLNESS BREAK ON NOVEMBER 4, 2023 (SATURDAY)', '1.0 In line with our commitment to supporting the physical and mental health of our faculty, staff, and students, classes and regular university activities will also be suspended on November 4, 2023 Catitrddars)\r\n2.0 The extended Wellness Break aims to provide everyone with an opportunity to take a step back, relax, and engage in activities that rejuvenate their physical and mental health. Everyone is encouraged to use this time to engage in self-care, connect with loved ones, or participate in wellness-related activities of your choice;\r\n3.0 The following shall be observed during the extended wellness break:\r\n3.1 Suspension of any academic activities, such as synchronous and asynchronous activities;\r\n3.2 Suspension of office work except for security, utility and farm workers (e.g. animal caretakers);\r\n3.3 Instructors and professors are advised not to set deadlines or deliverables from students, nor should they upload class materials and or any supplemental reading; and\r\n3.4 No meetings or webinars, except those prior scheduled by regional, national and international organizations;\r\n4.0 Contract of Service and Job Order workers shall be paid their wages during the abovementioned activity;\r\n5.0 Forinformation and guidance.', 9, 3, 9, '2023-11-02', 'Archived', 'file_6a55e023cb01e0.28333470.jpg', 'curl.jpg', 'image/jpeg', 155386, 'f13424bf900a9cedc3b81ce7ca1332251bea4674b372fc2f751a042f2aa4c99b', 1, '2026-07-14 15:07:15', NULL, NULL, 'Republic of the Philippines\r\nPresident Ramon Hagsapsay State University\r\n(Formerly Ramon Magsaysay Technological University)\r\nIba, Zambales, Philippines 2201\r\nEmail: universitypresident@prmsu.edu.ph Telefax: (047) 811-1083\r\nOFFICE OF THE UNIVERSITY PRESIDENT\r\n-000--\r\nMEMORANDUM\r\nNo. 114-A s. 2023\r\nTO: ALL UNIVERSITY OFFICIALS, FACULTY AND NON-TEACHING STAFF\r\n(INCLUDING UNDER CONTRACT OF SERVICE AND JOB ORDER)\r\nALL STUDENTS\r\nFROM: UNIVERSITY PRESIDENT\r\nDATE: NOVEMBER 2, 2023\r\nSUBJECT: EXTENDED PRMSU WELLNESS BREAK ON NOVEMBER 4, 2023 (SATURDAY)\r\n1.0 In line with our commitment to supporting the physical and mental health of our faculty, staff, and\r\nstudents, classes and regular university activities will also be suspended on November 4, 2023\r\nCatitrddars)\r\n2.0 The extended Wellness Break aims to provide everyone with an opportunity to take a step back, relax,\r\nand engage in activities that rejuvenate their physical and mental health. Everyone is encouraged to\r\nuse this time to engage in self-care, connect with loved ones, or participate in wellness-related activities\r\nof your choice;\r\n3.0 The following shall be observed during the extended wellness break:\r\n3.1 Suspension of any academic activities, such as synchronous and asynchronous activities;\r\n3.2 Suspension of office work except for security, utility and farm workers (e.g. animal caretakers);\r\n3.3 Instructors and professors are advised not to set deadlines or deliverables from students, nor\r\nshould they upload class materials and or any supplemental reading; and\r\n3.4 No meetings or webinars, except those prior scheduled by regional, national and international\r\norganizations;\r\n4.0 Contract of Service and Job Order workers shall be paid their wages during the abovementioned\r\nactivity;\r\n5.0 For information and guidance.\r\n\r\nROY N. VILLALOBOS, DPA', 91.50, 'verified', 19, '2026-07-14 15:07:15', 'Verified during document creation.', '2026-07-14 15:07:15', 19, NULL, NULL, NULL, NULL, NULL, 'Done', '2026-07-14 15:11:36', 20, 19, '2026-07-14 15:07:15', '2026-07-14 15:11:36', NULL, NULL, NULL),
	(30, '2026-IBA-00007', 'No. 12 s. 2026', 'MEMORANDUM', NULL, NULL, '34705d5d90e2c811066debb40d87f367a56acc2c166f5a088ca0b7ada9052cb1', 'CLASS SUSPENSION AT IBA CAMPUS ON JANUARY 23, 2026,12:00 NOON ONWARDS', '1.0 Inline with the conduct of the "AGRAKSAK 2026: Rambak ti Talento" on January 23, 2026, you are hereby advised to suspend classes at the Iba Campus from 12:00 noon onwards.; \r\n2.0 For information and participation.', 9, 3, 9, '2026-01-22', 'Archived', 'file_6a55e41b7b6380.13570852.jpg', 'gege.jpg', 'image/jpeg', 95602, 'b6ee18d64d3cc5d993c23dab204052c54aa85c977289ca8bc29931400f20efa4', 1, '2026-07-14 15:24:11', NULL, NULL, 'President Ramon Magsaysay State University\r\nIba, Zambales, Philippines 2201\r\nEmail: universitypresident@prmsu.edu.ph | rmtupresident@yahoo.com\r\nWebsite: https://prmsu.edu.ph/PRMSU\r\nTelephone No.: (047) 602-6120-24\r\n\r\nOFFICE OF THE UNIVERSITY PRESIDENT\r\n--000--\r\nNo. 12 s. 2026\r\nTO : ALL COLLEGE DEANS (PRMSU IBA CAMPUS)\r\nFROM: : UNIVERSITY PRESIDENT\r\nDATE: JANUARY 22, 2026\r\nSUBJECT : CLASS SUSPENSION AT IBA CAMPUS ON JANUARY 23, 2026,12:00 NOON ONWARDS\r\n\r\n1.0 In line with the conduct of the "AGRAKSAK 2026: Rambak ti Talento" on January 23, 2026, you are hereby advised to suspend classes at the Iba Campus from 12:00 noon onwards.; \r\n2.0 For information and participation.\r\n\r\nROY N. VILLALOBOS, DPA', 83.50, 'verified', 19, '2026-07-14 15:24:11', 'Verified during document creation.', '2026-07-14 15:24:11', 19, NULL, NULL, NULL, NULL, NULL, 'Done', '2026-07-14 15:28:35', 20, 19, '2026-07-14 15:24:11', '2026-07-14 15:28:35', NULL, NULL, NULL),
